<html>
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>WEO Poster - Render</title>
  <style>
    html, body { margin: 0; padding: 0; background: #ffffff; }
    #stage { position: relative; width: 100vw; height: 100vh; overflow: hidden; background: #ffffff; }
    svg { display: block; }
  </style>
</head>
<body>
  <div id="stage"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    (function(){
      const syntax = `infographic list-row-horizontal-icon-arrow
    data
      title TEST
      desc Hello
      lists
        - label A
          value 1
          desc x
          icon chart line
    theme
      palette #002244 #6b7280 #f59e0b`;

      const stage = document.querySelector('#stage');

      // Render an infographic to SVG string.
      async function renderInfographicToSvg(s){
        const container = document.createElement('div');
        container.style.width = '800px';
        container.style.height = '600px';
        container.style.position = 'absolute';
        container.style.left = '-10000px';
        container.style.top = '0';
        document.body.appendChild(container);

        const infographic = new AntVInfographic.Infographic({
          container,
          width: '100%',
          height: '100%',
        });

        infographic.render(s);
        try { await (document.fonts?.ready || Promise.resolve()); } catch(e) {}
        infographic.render(s);

        // Try dataURL export if available
        let dataUrl = null;
        if (typeof infographic.toDataURL === 'function') {
          try { dataUrl = await infographic.toDataURL({ type: 'svg' }); } catch(e) {}
        }

        // Fallback: grab first svg in container
        let svgText = null;
        if (dataUrl && dataUrl.startsWith('data:image/svg+xml')) {
          svgText = decodeURIComponent(dataUrl.split(',')[1]);
        } else {
          const svgEl = container.querySelector('svg');
          if (svgEl) svgText = new XMLSerializer().serializeToString(svgEl);
        }

        container.remove();
        return svgText;
      }

      async function main(){
        const svg = await renderInfographicToSvg(syntax);
        stage.innerText = svg ? 'OK' : 'NO';
      }

      main().catch(err => { stage.innerText = String(err && err.stack || err); });
    })();
  </script>
</body>
</html>
