  <style>
    :root{
      --imf:#002244;
      --ink:#0b1220;
      --muted:#4b5563;
      --grid:#e5e7eb;
      --bg:#ffffff;
      --accent:#d97706; /* amber */
      --panel:#f8fafc;
    }
    html, body { margin:0; padding:0; background:var(--bg); }
    body { font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; }

    /* A0 portrait at ~150 DPI: 4961 x 7016 */
    #poster {
      width: 4961px;
      height: 7016px;
      position: relative;
      background: var(--bg);
      overflow: hidden;
    }

    .margin {
      position:absolute;
      left: 220px;
      top: 200px;
      right: 220px;
      bottom: 200px;
    }

    header {
      display:flex;
      gap: 60px;
      align-items: flex-end;
      border-bottom: 8px solid var(--imf);
      padding-bottom: 36px;
      margin-bottom: 44px;
    }
    h1{
      margin:0;
      font-size: 128px;
      line-height: 1.06;
      letter-spacing: -0.02em;
      color: var(--imf);
      flex: 1;
    }
    .subtitle{
      margin: 0 0 10px 0;
      color: var(--muted);
      font-size: 42px;
      line-height:1.4;
      max-width: 1400px;
    }

    .top-row{
      display:grid;
      grid-template-columns: 3fr 2fr;
      gap: 44px;
      align-items: stretch;
      margin-bottom: 44px;
    }

    .card{
      background: var(--panel);
      border: 2px solid #eef2f7;
      border-radius: 28px;
      padding: 40px;
      box-shadow: 0 0 0 rgba(0,0,0,0);
    }

    .kpi-grid{
      display:grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
    }

    .kpi{
      background:#ffffff;
      border: 2px solid #eef2f7;
      border-radius: 22px;
      padding: 26px 26px;
      min-height: 170px;
    }
    .kpi .value{
      font-size: 64px;
      font-weight: 800;
      color: var(--imf);
      margin-bottom: 10px;
      letter-spacing: -0.01em;
    }
    .kpi .label{
      font-size: 30px;
      color: var(--ink);
      margin-bottom: 8px;
      font-weight: 650;
    }
    .kpi .source{
      font-size: 24px;
      color: var(--muted);
    }

    .callout{
      background: #fff7ed;
      border: 3px solid var(--accent);
      border-radius: 28px;
      padding: 36px 40px;
      height: 100%;
      display:flex;
      flex-direction: column;
      justify-content: space-between;
    }
    .callout .tag{
      display:inline-block;
      font-size: 28px;
      color: var(--accent);
      letter-spacing: 0.08em;
      text-transform: uppercase;
      font-weight: 800;
      margin-bottom: 12px;
    }
    .callout .big{
      font-size: 72px;
      line-height: 1.08;
      font-weight: 900;
      color: #7c2d12;
      letter-spacing: -0.02em;
      margin: 0 0 12px 0;
    }
    .callout .desc{
      font-size: 34px;
      line-height: 1.45;
      color: #7c2d12;
      margin: 0;
    }

    .main{
      display:grid;
      grid-template-columns: 3fr 2fr;
      gap: 44px;
      align-items: start;
    }

    .section-title{
      font-size: 54px;
      margin: 0 0 18px 0;
      color: var(--ink);
      letter-spacing: -0.01em;
    }
    .section-sub{
      font-size: 30px;
      color: var(--muted);
      margin: 0 0 18px 0;
      line-height: 1.45;
    }

    .stack{ display:flex; flex-direction:column; gap: 34px; }

    .infobox{
      background:#ffffff;
      border: 2px solid #eef2f7;
      border-radius: 28px;
      padding: 26px;
    }
    .infobox .label{
      font-size: 28px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--imf);
      font-weight: 850;
      margin: 0 0 12px 0;
    }

    /* Make embedded svg crisp */
    .svg-wrap svg { width: 100%; height: auto; }

    footer{
      position:absolute;
      left: 220px;
      right: 220px;
      bottom: 140px;
      display:flex;
      justify-content: space-between;
      align-items: flex-end;
      color: var(--muted);
      font-size: 24px;
      border-top: 2px solid var(--grid);
      padding-top: 20px;
    }
    .foot-left{ max-width: 70%; line-height:1.4; }
    .foot-right{ text-align:right; }
  </style>
</head>
<body>
  <div id="poster">
    <div class="margin">
      <header>
        <div style="flex:1">
          <h1>Global Economy in the Shadow of War</h1>
          <p class="subtitle">IMF World Economic Outlook Trends 2024–2026 — persistent mediocrity with growing fragility.</p>
        </div>
        <div style="width: 980px; text-align:right;">
          <div style="font-size:28px; color:var(--muted); letter-spacing:0.06em; text-transform:uppercase; font-weight:800;">IMF–World Bank Annual Meetings</div>
          <div style="font-size:40px; color:var(--ink); font-weight:850; margin-top:8px;">Research Symposium Poster</div>
        </div>
      </header>

      <div class="top-row">
        <div class="card">
          <div style="display:flex; align-items:baseline; justify-content:space-between; gap: 24px;">
            <div>
              <div style="font-size:28px; letter-spacing:0.08em; text-transform:uppercase; color:var(--imf); font-weight:850;">At a glance</div>
              <div style="font-size:34px; margin-top:10px; color:var(--muted); line-height:1.45;">Eight WEO editions (Jul 2024–Apr 2026) keep global growth in a tight 3.0–3.3% band—below the ~3.8% pre‑pandemic average—while risk narratives increasingly emphasize downside tail events.</div>
            </div>
          </div>
          <div style="height: 22px"></div>
          <div class="kpi-grid">
            <div class="kpi">
              <div class="value">3.0%</div>
              <div class="label">Global Growth 2025 (projected)</div>
              <div class="source">Source: WEO Jul 2025 Update</div>
            </div>
            <div class="kpi">
              <div class="value">3.3%</div>
              <div class="label">Global Growth 2026 (projected)</div>
              <div class="source">Source: WEO Jan 2026 Update</div>
            </div>
            <div class="kpi">
              <div class="value">8</div>
              <div class="label">WEO editions reviewed</div>
              <div class="source">Jul 2024–Apr 2026</div>
            </div>
            <div class="kpi">
              <div class="value">Downside</div>
              <div class="label">Risk balance (all editions)</div>
              <div class="source">Consistent finding across WEOs</div>
            </div>
          </div>
        </div>

        <div class="callout">
          <div>
            <span class="tag">Persistent qualitative finding</span>
            <p class="big">“Tilted to the downside”</p>
            <p class="desc">Across every edition reviewed, the IMF frames the balance of risks as skewed toward adverse scenarios—even when headline growth remains stable.</p>
          </div>
          <div style="display:flex; gap:18px; align-items:center;">
            <div style="width:14px; height:80px; background:var(--accent); border-radius: 12px;"></div>
            <div style="font-size:30px; color:#7c2d12; line-height:1.45;">
              Trade policy shocks · Geopolitical fractures · Sticky services inflation · Tech re‑pricing
            </div>
          </div>
        </div>
      </div>

      <div class="main">
        <div class="stack">
          <div class="card">
            <h2 class="section-title">Global Growth Projections: A Narrow Band of Mediocrity</h2>
            <p class="section-sub">Headline projections across WEO editions cluster tightly. The story is not collapse, but stalled momentum—growth stuck near ~3.1% and repeatedly described as vulnerable to downside shocks.</p>
            <div class="infobox">
              <div class="label">Growth timeline (headline values / qualitative markers)</div>
              <div id="growthChart" class="svg-wrap"></div>
              <div style="height: 14px"></div>
              <div style="font-size:24px; color:var(--muted); line-height:1.45;">
                Notes: Several editions present growth qualitatively (“Slowing”, “Renewed pressure”). For visual continuity, qualitative markers are mapped to approximate positions within the 3.0–3.3% band.
              </div>
            </div>
          </div>

          <div class="card">
            <h2 class="section-title">Evolving Policy Priorities</h2>
            <p class="section-sub">The narrative spine: recommendations shift from managing disinflation and rebuilding fiscal buffers → strengthening frameworks and structural reforms → handling defense‑spending trade‑offs under heightened geopolitical risk.</p>
            <div class="infobox">
              <div class="label">Policy evolution timeline</div>
              <div id="policyTimeline" class="svg-wrap"></div>
            </div>
          </div>
        </div>

        <div class="stack">
          <div class="card">
            <h2 class="section-title">Dominant Downside Risks</h2>
            <p class="section-sub">Recurring risks intensify as themes rotate—from tariff escalation to security shocks to inflation persistence and AI/tech repricing risk.</p>
            <div class="infobox">
              <div id="risksList" class="svg-wrap"></div>
            </div>
          </div>

          <div class="card">
            <h2 class="section-title">Inflation Outlook and Monetary Policy</h2>
            <p class="section-sub">Global disinflation enables easing, but the path is uneven: US services inflation remains stickier, delaying a full return to target; by Apr 2026, renewed pressures re‑enter the narrative.</p>
            <div class="infobox">
              <div id="inflationList" class="svg-wrap"></div>
            </div>
          </div>

          <div class="card">
            <h2 class="section-title">Special Themes Across WEO Editions</h2>
            <p class="section-sub">Analytical chapters broaden from macro stabilization toward the political economy of reform and inclusive supply‑side capacity.</p>
            <div class="infobox">
              <div id="themesList" class="svg-wrap"></div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <footer>
      <div class="foot-left">Data: IMF World Economic Outlook (WEO) editions and updates (Jul 2024–Apr 2026). Poster synthesizes reported headline projections and recurring qualitative assessments.</div>
      <div class="foot-right">A0 portrait • Rendered Apr 25, 2026 (UTC)</div>
    </footer>
  </div>

  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    // Helper: render an AntV Infographic and return SVG string.
    async function renderInfographicToSvg(syntax, size){
      const container = document.createElement('div');
      container.style.width = (size?.width || 1200) + 'px';
      container.style.height = (size?.height || 800) + 'px';
      container.style.position = 'absolute';
      container.style.left = '-10000px';
      container.style.top = '0';
      document.body.appendChild(container);

      const infographic = new AntVInfographic.Infographic({
        container,
        width: '100%',
        height: '100%',
      });

      infographic.render(syntax);
      try { await (document.fonts?.ready || Promise.resolve()); } catch(e) {}
      infographic.render(syntax);

      let dataUrl = null;
      if (typeof infographic.toDataURL === 'function') {
        try { dataUrl = await infographic.toDataURL({ type: 'svg' }); } catch(e) {}
      }

      let svgText = null;
      if (dataUrl && dataUrl.startsWith('data:image/svg+xml')) {
        svgText = decodeURIComponent(dataUrl.split(',')[1]);
      } else {
        const svgEl = container.querySelector('svg');
        if (svgEl) svgText = new XMLSerializer().serializeToString(svgEl);
      }

      container.remove();
      return svgText;
    }

    function mountSvg(targetSelector, svgText){
      const target = document.querySelector(targetSelector);
      if (!target) return;
      target.innerHTML = svgText || '';
    }

    (async function(){
      // --- Infographic syntaxes (skill-driven) ---

      const palette = 'palette #002244 #6b7280 #d97706';

      // Growth: map qualitative markers into band for continuity.
      const growthSyntax = `infographic chart-line-plain-text
  data
    title Headline Global Growth (WEO editions)
    desc Forecasts cluster in a tight 3.0–3.3% band.
    values
      - label Jul 2024\n(2025: 3.3)
        value 3.3
      - label Oct 2024\n(~3.3)
        value 3.3
      - label Jan 2025\n(2025: 3.3)
        value 3.3
      - label Apr 2025\nSlowing
        value 3.15
      - label Jul 2025\n(2025: 3.0)
        value 3.0
      - label Oct 2025\nSlowing
        value 3.12
      - label Jan 2026\n(2026: 3.2)
        value 3.2
      - label Apr 2026\nRenewed\npressure
        value 3.08
  theme
    ${palette}`;

      const policySyntax = `infographic sequence-timeline-rounded-rect-node
  data
    title Policy priorities (IMF narrative)
    desc From cautious easing to buffers to defense-spending trade-offs.
    sequences
      - label Mid‑2024
        desc Manage disinflation; careful easing
      - label Late‑2024
        desc Monetary pivot; fiscal sustainability
      - label Early‑2025
        desc Rebuild buffers; inclusion & demographics
      - label Mid‑2025
        desc Predictability amid tariff uncertainty
      - label Late‑2025
        desc Stronger frameworks; cautious industrial policy
      - label Early‑2026
        desc Agile policy; defense-spending trade‑offs
  theme
    ${palette}`;

      const risksSyntax = `infographic list-column-vertical-icon-arrow
  data
    title Downside risks (recurring)
    desc Risks repeatedly framed as skewed to adverse outcomes.
    lists
      - label Trade policy escalation
        desc Tariffs and retaliation; front‑loading masks damage
        icon flag
      - label Geopolitical tensions
        desc Security shocks; war risk increasingly central
        icon shield
      - label Technology re‑evaluation
        desc AI/tech expectations vulnerable to repricing
        icon cpu
      - label Persistent services inflation
        desc Especially sticky in the United States
        icon fire
  theme
    ${palette}`;

      const inflationSyntax = `infographic list-row-horizontal-icon-arrow
  data
    title Inflation & monetary policy
    desc Global disinflation continues, but unevenly.
    lists
      - label Global trend
        desc Declining inflation supports easing through 2026
        icon chart line
      - label US exception
        desc Above-target longer; services inflation sticky
        icon alert triangle
      - label Pivot timing
        desc "Policy pivot" narrative emerges in late 2024
        icon rotate
      - label Renewed pressures
        desc Defense spending and disruptions re-enter by Apr 2026
        icon warning
  theme
    ${palette}`;

      const themesSyntax = `infographic list-grid-badge-card
  data
    title Rotating analytical themes
    lists
      - label Industrial policy
        icon building
      - label Social acceptability of reforms
        icon users
      - label Aging & demographics
        icon hourglass
      - label Gender & migration integration
        icon user plus
      - label Disinflation mechanics
        icon activity
  theme
    ${palette}`;

      // Render and mount
      const growthSvg = await renderInfographicToSvg(growthSyntax, {width: 2200, height: 1100});
      mountSvg('#growthChart', growthSvg);

      const policySvg = await renderInfographicToSvg(policySyntax, {width: 2200, height: 900});
      mountSvg('#policyTimeline', policySvg);

      const risksSvg = await renderInfographicToSvg(risksSyntax, {width: 1500, height: 900});
      mountSvg('#risksList', risksSvg);

      const inflSvg = await renderInfographicToSvg(inflationSyntax, {width: 1500, height: 720});
      mountSvg('#inflationList', inflSvg);

      const themesSvg = await renderInfographicToSvg(themesSyntax, {width: 1500, height: 760});
      mountSvg('#themesList', themesSvg);

      // Signal ready for headless capture
      document.documentElement.setAttribute('data-ready', 'true');
    })().catch(err => {
      console.error(err);
      document.documentElement.setAttribute('data-ready', 'error');
      document.body.innerText = String(err && err.stack || err);
    });
  </script>
</body>
</html>
